import { useEffect, useState } from 'react';
import { useLocation, useNavigate, useParams } from 'react-router-dom';
import { Button } from '@/components/ui/Button.js';
import { EmptyState } from '@/components/ui/EmptyState.js';
import { Icon } from '@/components/ui/Icon.js';
import { getMeta, type MetaShape } from '@/db/schema.js';
import { dirOf } from '@/features/assistant/richText.js';
import { t } from '@/i18n/index.js';
import { relativeTime } from '@/lib/format.js';
import { useLinkHosts } from '@/lib/useConfig.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { actionView } from './action.js';
import { markInboxRead, refreshInbox } from './inbox.js';
import { NotificationAction } from './NotificationAction.js';
import styles from './MessagePage.module.css';

/**
 * One notification on a page of its own, at /notifications/:id, with its
 * button. A pop-up whose message carries an external link opens this page,
 * never the link: an address never travels in a push, and a browser may
 * open another site only from a press (plan decision 2). The message is
 * read from the bell's local copy; one not in it yet is fetched once.
 */
export function MessagePage(): React.JSX.Element {
  const { notificationId = '' } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const links = useLinkHosts();
  const inbox = useLiveQuery<MetaShape['inbox'] | undefined>(() => getMeta('inbox'), undefined, []);
  // Whether the server was asked for the newest page, and what came of it.
  const [fetched, setFetched] = useState<boolean | undefined>();

  const item = inbox?.notifications.find((one) => one.id === notificationId);
  const unread = item !== undefined && item.readAt === undefined;

  useEffect(() => {
    let live = true;
    void refreshInbox().then((ok) => {
      if (live) setFetched(ok);
    });
    return () => {
      live = false;
    };
  }, [notificationId]);

  // Shown is read, as in the bell.
  useEffect(() => {
    if (unread) void markInboxRead([notificationId]);
  }, [unread, notificationId]);

  const leave = (): void => {
    if (location.key === 'default') void navigate('/', { replace: true });
    else void navigate(-1);
  };
  const toToday = (): void => {
    void navigate('/', { replace: true });
  };

  return (
    <main className={styles.screen} dir={item === undefined ? undefined : dirOf(item.title)}>
      <header className={styles.subHead}>
        <button type="button" className={styles.back} aria-label={t('action.back')} onClick={leave}>
          <Icon name="chevronLeft" size={22} weight={2} />
        </button>
      </header>
      {item !== undefined && (
        <article className={styles.message} aria-labelledby="message-title">
          <time className={styles.time} dateTime={item.createdAt} dir="ltr">
            {relativeTime(item.createdAt)}
          </time>
          <h1 className={styles.title} id="message-title" dir="auto">
            {item.title}
          </h1>
          <p className={styles.body} dir="auto">
            {item.body}
          </p>
          <NotificationAction
            view={actionView(item, links.hosts, links.answered)}
            onOpen={(path) => {
              void navigate(path);
            }}
          />
        </article>
      )}
      {item === undefined && fetched === undefined && (
        <span role="status" className="sr-only">
          {t('message.loading')}
        </span>
      )}
      {item === undefined && fetched !== undefined && (
        <div className={styles.outcome}>
          <EmptyState
            middle
            heading="h1"
            tone="quiet"
            icon={fetched ? 'info' : 'wifiOff'}
            title={fetched ? t('message.goneTitle') : t('message.offlineTitle')}
            body={fetched ? t('message.goneBody') : t('message.offlineBody')}
            actions={
              <Button variant="secondary" onClick={toToday}>
                {t('form.back')}
              </Button>
            }
          />
        </div>
      )}
    </main>
  );
}
